INSERT INTO "requests" ("id", "submissionId", "type", "title", "createdBy", "createdByUsername", "createdById", "createdByRole", "createdByDesignation", "createdByEmployeeId", "createdByDepartment", "createdByPhone", "payload", "remarks", "target", "status", "forwardedTo", "uploadedFile", "signatureFrom", "signatureStatus", "officialDocument", "circular", "createdAt", "updatedAt") VALUES (E'1663', E'2111', E'attendance-report', E'Attendance report: 2026-11-04 to 2026-11-04', E'RITHANYA D', E'rithanyad', E'SMIB-EMP-e861d360-f148-4f68-afbc-c479ae09febb', E'intern', E'PCB Design Intern', E'MIB09', E'PCB Designs & Fabrication Team', E'9384304331', '{"fromDate": "2026-11-04", "toDate": "2026-11-04", "remarks": "The schematic design for Sections A (Power Supply Unit) and D (User Interface and Logic Block) of the Motor Starter PCB project is fully completed, validated with zero compilation errors, and exported as a Smart PDF. All power connections, SWD programming headers, local decoupling capacitor banks, and TM1637 display driver lines have been thoroughly verified for design integrity. The generated schematics have been emailed to Mr. Golla Kumar for review and approval, while Sections B and C are currently being handled by Smrithi, and any requested updates will be implemented upon feedback.", "daysRecorded": 1, "attendance": [{"id": "78b416b4-0437-4afa-b995-28ff388cb442", "userId": "SMIB-EMP-e861d360-f148-4f68-afbc-c479ae09febb", "username": "rithanyad", "fullName": "RITHANYA D", "employeeId": "MIB09", "date": "2026-11-04", "checkIn": "2026-11-04T03:10:32.302Z"}], "approvalChain": ["vishnuu", "hareeshv", "santhanakumarv", "gkbharath"], "currentApproverIndex": 3, "guideId": "SMIB-EMP-5c6151ea-f197-40ad-9eb4-69cc3e1cd5e3", "guideUsername": "vishnuu", "comments": [{"by": "gkbharath", "comment": "", "decision": "approve", "stageIndex": 3, "at": "2026-11-05T03:22:54.375Z"}, {"by": "santhanakumarv", "comment": "", "decision": "approve", "stageIndex": 2, "at": "2026-11-05T03:17:06.210Z"}, {"by": "hareeshv", "comment": "", "decision": "approve", "stageIndex": 1, "at": "2026-11-05T02:56:43.554Z"}, {"by": "vishnuu", "comment": "", "decision": "recommend", "stageIndex": 0, "at": "2026-11-04T11:32:58.571Z"}]}'::jsonb, E'The schematic design for Sections A (Power Supply Unit) and D (User Interface and Logic Block) of the Motor Starter PCB project is fully completed, validated with zero compilation errors, and exported as a Smart PDF. All power connections, SWD programming headers, local decoupling capacitor banks, and TM1637 display driver lines have been thoroughly verified for design integrity. The generated schematics have been emailed to Mr. Golla Kumar for review and approval, while Sections B and C are currently being handled by Smrithi, and any requested updates will be implemented upon feedback.', E'admin', E'approved', E'gkbharath', NULL, NULL, NULL, NULL, NULL, E'2026-11-04T11:19:43.859Z', E'2026-11-05T03:22:54.377Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "requests" ("id", "submissionId", "type", "title", "createdBy", "createdByUsername", "createdById", "createdByRole", "createdByDesignation", "createdByEmployeeId", "createdByDepartment", "createdByPhone", "payload", "remarks", "target", "status", "forwardedTo", "uploadedFile", "signatureFrom", "signatureStatus", "officialDocument", "circular", "createdAt", "updatedAt") VALUES (E'2745', E'9200', E'attendance-report', E'Attendance report: 2026-11-04 to 2026-11-04', E'VISHNU VARSHINI M', E'vishnuu', E'SMIB-EMP-5c6151ea-f197-40ad-9eb4-69cc3e1cd5e3', E'employee', E'PCB & EMS/IoT Designer-T', E'MIB05', E'PCB Designs & Fabrication Team', E'6380551370', '{"fromDate": "2026-11-04", "toDate": "2026-11-04", "remarks": "DAILY WORK REPORT\n\nDate: 04 November 2026\nLocation: Mudhalvar Padaipagam, Georgetown\n\n1. PCB Design Training: Conducted PCB design training for a new company joinee, explaining the fundamentals of PCB design and developing two basic circuits using KiCad.\n\n2. Company Database & Business Development: Updated the company database and sent emails to other companies regarding project opportunities and potential collaborations.\n\n3. PCB Reverse Engineering Analysis: Studied the reverse engineering process for the provided PCB, focusing on the feasibility, methodology, and technical considerations involved in analyzing a four-layer PCB.", "daysRecorded": 1, "attendance": [{"id": "b8c299ab-86df-484c-9cfd-b55ab4c1b399", "userId": "SMIB-EMP-5c6151ea-f197-40ad-9eb4-69cc3e1cd5e3", "username": "vishnuu", "fullName": "VISHNU VARSHINI M", "employeeId": "MIB05", "date": "2026-11-04", "checkIn": "2026-11-04T03:17:25.518Z"}], "approvalChain": ["hareeshv", "santhanakumarv", "gkbharath"], "currentApproverIndex": 2, "comments": [{"by": "gkbharath", "comment": "", "decision": "approve", "stageIndex": 2, "at": "2026-11-05T03:23:09.389Z"}, {"by": "santhanakumarv", "comment": "", "decision": "approve", "stageIndex": 1, "at": "2026-11-05T03:17:13.015Z"}, {"by": "hareeshv", "comment": "", "decision": "approve", "stageIndex": 0, "at": "2026-11-05T02:56:46.923Z"}]}'::jsonb, E'DAILY WORK REPORT\n\nDate: 04 November 2026\nLocation: Mudhalvar Padaipagam, Georgetown\n\n1. PCB Design Training: Conducted PCB design training for a new company joinee, explaining the fundamentals of PCB design and developing two basic circuits using KiCad.\n\n2. Company Database & Business Development: Updated the company database and sent emails to other companies regarding project opportunities and potential collaborations.\n\n3. PCB Reverse Engineering Analysis: Studied the reverse engineering process for the provided PCB, focusing on the feasibility, methodology, and technical considerations involved in analyzing a four-layer PCB.', E'admin', E'approved', E'gkbharath', NULL, NULL, NULL, NULL, NULL, E'2026-11-04T11:14:48.705Z', E'2026-11-05T03:23:09.389Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "requests" ("id", "submissionId", "type", "title", "createdBy", "createdByUsername", "createdById", "createdByRole", "createdByDesignation", "createdByEmployeeId", "createdByDepartment", "createdByPhone", "payload", "remarks", "target", "status", "forwardedTo", "uploadedFile", "signatureFrom", "signatureStatus", "officialDocument", "circular", "createdAt", "updatedAt") VALUES (E'1000', E'4939', E'attendance-report', E'Attendance report: 2026-11-03 to 2026-11-03', E'RITHANYA D', E'rithanyad', E'SMIB-EMP-e861d360-f148-4f68-afbc-c479ae09febb', E'intern', E'PCB Design Intern', E'MIB09', E'PCB Designs & Fabrication Team', E'9384304331', '{"fromDate": "2026-11-03", "toDate": "2026-11-03", "remarks": "Today''s design session focused on completing the core controller and telemetry interface for Section D (UI and Logic Block) of the Motor Starter PCB in Altium Designer. After finalizing the STM32G431CBT6 microcontroller (U401) power supply connections, 100 nF decoupling capacitor bank (C401\u2013C405), reset RC filter (C406), 10 k\u03a9 BOOT0 pulldown resistor (R401), and 5-pin SWD programming header (J401), attention turned to the display subsystem. You configured the bare 20-pin TM1637 IC driver in an SOIC-20 package (U402), connected its power rail to +5V and ground to GND, and wired a local 100 nF SMT ceramic decoupling capacitor (C407) across pins 20 and 10 to ensure robust power supply noise suppression before routing the serial CLK and DIO telemetry lines to the MCU.", "daysRecorded": 1, "attendance": [{"id": "935b72d3-b93e-432b-ac20-d3e768fb14a0", "userId": "SMIB-EMP-e861d360-f148-4f68-afbc-c479ae09febb", "username": "rithanyad", "fullName": "RITHANYA D", "employeeId": "MIB09", "date": "2026-11-03", "checkIn": "2026-11-03T03:31:12.076Z", "checkOut": "2026-11-03T11:30:16.819Z"}], "approvalChain": ["vishnuu", "hareeshv", "santhanakumarv", "gkbharath"], "currentApproverIndex": 3, "guideId": "SMIB-EMP-5c6151ea-f197-40ad-9eb4-69cc3e1cd5e3", "guideUsername": "vishnuu", "comments": [{"by": "gkbharath", "comment": "", "decision": "approve", "stageIndex": 3, "at": "2026-11-05T03:23:14.337Z"}, {"by": "santhanakumarv", "comment": "", "decision": "approve", "stageIndex": 2, "at": "2026-11-05T03:17:14.706Z"}, {"by": "hareeshv", "comment": "", "decision": "approve", "stageIndex": 1, "at": "2026-11-05T02:56:49.565Z"}, {"by": "vishnuu", "comment": "", "decision": "recommend", "stageIndex": 0, "at": "2026-11-04T03:18:20.650Z"}]}'::jsonb, E'Today''s design session focused on completing the core controller and telemetry interface for Section D (UI and Logic Block) of the Motor Starter PCB in Altium Designer. After finalizing the STM32G431CBT6 microcontroller (U401) power supply connections, 100 nF decoupling capacitor bank (C401–C405), reset RC filter (C406), 10 kΩ BOOT0 pulldown resistor (R401), and 5-pin SWD programming header (J401), attention turned to the display subsystem. You configured the bare 20-pin TM1637 IC driver in an SOIC-20 package (U402), connected its power rail to +5V and ground to GND, and wired a local 100 nF SMT ceramic decoupling capacitor (C407) across pins 20 and 10 to ensure robust power supply noise suppression before routing the serial CLK and DIO telemetry lines to the MCU.', E'admin', E'approved', E'gkbharath', NULL, NULL, NULL, NULL, NULL, E'2026-11-03T11:55:44.744Z', E'2026-11-05T03:23:14.337Z') ON CONFLICT ("id") DO NOTHING;
