INSERT INTO "requests" ("id", "submissionId", "type", "title", "createdBy", "createdByUsername", "createdById", "createdByRole", "createdByDesignation", "createdByEmployeeId", "createdByDepartment", "createdByPhone", "payload", "remarks", "target", "status", "forwardedTo", "uploadedFile", "signatureFrom", "signatureStatus", "officialDocument", "circular", "createdAt", "updatedAt") VALUES (E'1303', E'9860', E'attendance-report', E'Attendance report: 2026-10-30 to 2026-10-30', E'SMRITHI K', E'smrithik', E'SMIB-EMP-26f786a8-f668-447c-996c-b5e875867e13', E'intern', E'PCB Design Intern', E'MIB08', E'PCB Designs & Fabrication Team', E'8610492864', '{"fromDate": "2026-10-30", "toDate": "2026-10-30", "remarks": "Task 1: Finalized the system block diagram for the programmable electronic motor starter.\nTask 2: Completed a full BOM audit and optimization, shifting from modular breakout boards to a fully discrete, SMT-heavy design suitable for mass manufacturing.\nTask 3: Resolved hardware design traps, specifically focusing on the 440V galvanic isolation barrier (AMC1311DWV), SSR thermal derating limits (85\u00b0C KSD9700), and UI mechanical durability (22mm industrial switches).\nTask 4: Prepared the final component list for the transition into Altium Designer schematic capture.", "daysRecorded": 1, "attendance": [{"id": "7d71f70e-3c6d-4de6-bdae-2b438012b3ef", "userId": "SMIB-EMP-26f786a8-f668-447c-996c-b5e875867e13", "username": "smrithik", "fullName": "SMRITHI K", "employeeId": "MIB08", "date": "2026-10-30", "checkIn": "2026-10-30T03:12:58.782Z", "checkOut": "2026-10-30T12:47:08.982Z"}], "approvalChain": ["sabir", "hareeshv", "santhanakumarv", "gkbharath"], "currentApproverIndex": 0, "guideId": "SMIB-EMP-cb29066e-397b-4d3d-bd88-04ee5d654d69", "guideUsername": "sabir"}'::jsonb, E'Task 1: Finalized the system block diagram for the programmable electronic motor starter.\nTask 2: Completed a full BOM audit and optimization, shifting from modular breakout boards to a fully discrete, SMT-heavy design suitable for mass manufacturing.\nTask 3: Resolved hardware design traps, specifically focusing on the 440V galvanic isolation barrier (AMC1311DWV), SSR thermal derating limits (85°C KSD9700), and UI mechanical durability (22mm industrial switches).\nTask 4: Prepared the final component list for the transition into Altium Designer schematic capture.', E'admin', E'pending', NULL, NULL, NULL, NULL, NULL, NULL, E'2026-10-30T12:48:54.210Z', NULL) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "requests" ("id", "submissionId", "type", "title", "createdBy", "createdByUsername", "createdById", "createdByRole", "createdByDesignation", "createdByEmployeeId", "createdByDepartment", "createdByPhone", "payload", "remarks", "target", "status", "forwardedTo", "uploadedFile", "signatureFrom", "signatureStatus", "officialDocument", "circular", "createdAt", "updatedAt") VALUES (E'9752', E'2054', E'attendance-report', E'Attendance report: 2026-10-30 to 2026-10-30', E'VISHNU VARSHINI M', E'vishnuu', E'SMIB-EMP-5c6151ea-f197-40ad-9eb4-69cc3e1cd5e3', E'employee', E'PCB & EMS/IoT Designer-T', E'MIB05', E'PCB Designs & Fabrication Team', E'6380551370', '{"fromDate": "2026-10-30", "toDate": "2026-10-30", "remarks": "DAILY WORK REPORT\n\n1. SSR Project \u2013 Circuit Design\n   \n   - Worked on circuit-level connections based on the finalized block diagram.\n   - Reviewed component interconnections and signal flow between different circuit blocks.\n\n2. Adapter Project \u2013 Technical Analysis\n   \n   - Analysed the adapter reference and project requirements.\n   - Reviewed the feasibility of adapting the existing design with an Indian-standard plug pin.\n\n3. Marketing Agency Coordination\n   \n   - Contacted marketing agencies for project-related follow-ups.\n   - Requested quotations and gathered preliminary details for further evaluation.", "daysRecorded": 1, "attendance": [{"id": "a5a3a10d-5a7b-4901-b247-6caf3f51c5c0", "userId": "SMIB-EMP-5c6151ea-f197-40ad-9eb4-69cc3e1cd5e3", "username": "vishnuu", "fullName": "VISHNU VARSHINI M", "employeeId": "MIB05", "date": "2026-10-30", "checkIn": "2026-10-30T03:27:27.566Z"}], "approvalChain": ["hareeshv", "santhanakumarv", "gkbharath"], "currentApproverIndex": 0}'::jsonb, E'DAILY WORK REPORT\n\n1. SSR Project – Circuit Design\n   \n   - Worked on circuit-level connections based on the finalized block diagram.\n   - Reviewed component interconnections and signal flow between different circuit blocks.\n\n2. Adapter Project – Technical Analysis\n   \n   - Analysed the adapter reference and project requirements.\n   - Reviewed the feasibility of adapting the existing design with an Indian-standard plug pin.\n\n3. Marketing Agency Coordination\n   \n   - Contacted marketing agencies for project-related follow-ups.\n   - Requested quotations and gathered preliminary details for further evaluation.', E'admin', E'pending', NULL, NULL, NULL, NULL, NULL, NULL, E'2026-10-30T11:17:36.840Z', NULL) ON CONFLICT ("id") DO NOTHING;
