INSERT INTO "requests" ("id", "submissionId", "type", "title", "createdBy", "createdByUsername", "createdById", "createdByRole", "createdByDesignation", "createdByEmployeeId", "createdByDepartment", "createdByPhone", "payload", "remarks", "target", "status", "forwardedTo", "uploadedFile", "signatureFrom", "signatureStatus", "officialDocument", "circular", "createdAt", "updatedAt") VALUES (E'6732', E'1169', E'attendance-report', E'Attendance report: 2026-10-26 to 2026-10-26', E'MATHIYAZHAGAN D', E'mathi', E'SMIB-EMP-ece437f0-46b4-4c26-acda-c6164dadef01', E'intern', E'PCB Design Intern', E'MIB06', E'PCB Designs & Fabrication Team', E'8056197704', '{"fromDate": "2026-10-26", "toDate": "2026-10-26", "remarks": "Today''s work report \n\nWork Summary:\nToday, I researched and reviewed the websites of companies working in electronics design, embedded hardware, PCB design, IoT, and automation.\n\nTasks Completed:\n\n1. Reviewed the company website of DSIB Technologies.\n2. Reviewed Circuitronica''s website and its business domain.\n3. Reviewed RV Circuits'' website and its services.\n4. Reviewed Dexcel Designs'' website and its areas of specialization.\n5. Identified and organized the companies'' domains based on their technical services.\n6. Submitted the college data base", "daysRecorded": 1, "attendance": [{"id": "33fef29c-df11-4af2-849b-8c66f37ef777", "userId": "SMIB-EMP-ece437f0-46b4-4c26-acda-c6164dadef01", "username": "mathi", "fullName": "MATHIYAZHAGAN D", "employeeId": "MIB06", "date": "2026-10-26", "checkIn": "2026-10-26T03:36:59.493Z", "checkOut": "2026-10-26T12:00:47.980Z"}], "approvalChain": ["sabir", "hareeshv", "santhanakumarv", "gkbharath"], "currentApproverIndex": 3, "guideId": "SMIB-EMP-cb29066e-397b-4d3d-bd88-04ee5d654d69", "guideUsername": "sabir", "comments": [{"by": "gkbharath", "comment": "", "decision": "approve", "stageIndex": 3, "at": "2026-10-30T09:13:47.122Z"}, {"by": "santhanakumarv", "comment": "", "decision": "approve", "stageIndex": 2, "at": "2026-10-30T09:13:05.502Z"}, {"by": "hareeshv", "comment": "", "decision": "approve", "stageIndex": 1, "at": "2026-10-30T06:06:15.606Z"}, {"by": "sabir", "comment": "", "decision": "recommend", "stageIndex": 0, "at": "2026-10-30T03:32:11.788Z"}]}'::jsonb, E'Today''s work report \n\nWork Summary:\nToday, I researched and reviewed the websites of companies working in electronics design, embedded hardware, PCB design, IoT, and automation.\n\nTasks Completed:\n\n1. Reviewed the company website of DSIB Technologies.\n2. Reviewed Circuitronica''s website and its business domain.\n3. Reviewed RV Circuits'' website and its services.\n4. Reviewed Dexcel Designs'' website and its areas of specialization.\n5. Identified and organized the companies'' domains based on their technical services.\n6. Submitted the college data base', E'admin', E'approved', E'gkbharath', NULL, NULL, NULL, NULL, NULL, E'2026-10-26T13:09:37.195Z', E'2026-10-30T09:13:47.122Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "requests" ("id", "submissionId", "type", "title", "createdBy", "createdByUsername", "createdById", "createdByRole", "createdByDesignation", "createdByEmployeeId", "createdByDepartment", "createdByPhone", "payload", "remarks", "target", "status", "forwardedTo", "uploadedFile", "signatureFrom", "signatureStatus", "officialDocument", "circular", "createdAt", "updatedAt") VALUES (E'6548', E'5244', E'attendance-report', E'Attendance report: 2026-10-26 to 2026-10-26', E'RITHANYA D', E'rithanyad', E'SMIB-EMP-e861d360-f148-4f68-afbc-c479ae09febb', E'intern', E'PCB Design Intern', E'MIB09', E'PCB Designs & Fabrication Team', E'9384304331', '{"fromDate": "2026-10-26", "toDate": "2026-10-26", "remarks": "Session Summary\n\n- Studied the project requirements for developing an SSR-based electronic motor starter supporting single-phase and three-phase motors.\n- Reviewed the required protection functions, including over-voltage, under-voltage, overload, dry-run and phase-failure protection.\n- Discussed the feasibility of a common control platform for both motor configurations.\n- Identified the major system sections: Main Control PCB, Display and Keypad PCB, and Power Interface and Protection Assembly.\n- Prepared a preliminary list of component categories with proposed specifications, quantities and purposes.\n- Reviewed possible microcontroller options and identified motor specifications required before final component selection.\n\nOutcome\n- Gained an understanding of the proposed motor starter architecture and its major functional blocks.\n- Prepared an initial component list to support further circuit design.\n- Identified pending technical requirements, including motor ratings, current-sensing specifications and SSR selection criteria.\n- Established the next steps for preliminary schematic development and design review.\n\nNext Plan\nPrepare the system block diagram, finalize the preliminary controller input/output requirements and begin the low-voltage control circuit schematic for the upcoming design submission.", "daysRecorded": 1, "attendance": [{"id": "68b176a6-2aed-4ab9-860f-4ee4c66d5503", "userId": "SMIB-EMP-e861d360-f148-4f68-afbc-c479ae09febb", "username": "rithanyad", "fullName": "RITHANYA D", "employeeId": "MIB09", "date": "2026-10-26", "checkIn": "2026-10-26T02:52:46.332Z", "checkOut": "2026-10-26T11:57:02.048Z"}], "approvalChain": ["vishnuu", "hareeshv", "santhanakumarv", "gkbharath"], "currentApproverIndex": 3, "guideId": "SMIB-EMP-5c6151ea-f197-40ad-9eb4-69cc3e1cd5e3", "guideUsername": "vishnuu", "comments": [{"by": "gkbharath", "comment": "", "decision": "approve", "stageIndex": 3, "at": "2026-10-27T03:25:13.763Z"}, {"by": "santhanakumarv", "comment": "", "decision": "approve", "stageIndex": 2, "at": "2026-10-27T03:24:33.245Z"}, {"by": "hareeshv", "comment": "", "decision": "approve", "stageIndex": 1, "at": "2026-10-27T03:18:26.724Z"}, {"by": "vishnuu", "comment": "", "decision": "recommend", "stageIndex": 0, "at": "2026-10-26T13:02:58.020Z"}]}'::jsonb, E'Session Summary\n\n- Studied the project requirements for developing an SSR-based electronic motor starter supporting single-phase and three-phase motors.\n- Reviewed the required protection functions, including over-voltage, under-voltage, overload, dry-run and phase-failure protection.\n- Discussed the feasibility of a common control platform for both motor configurations.\n- Identified the major system sections: Main Control PCB, Display and Keypad PCB, and Power Interface and Protection Assembly.\n- Prepared a preliminary list of component categories with proposed specifications, quantities and purposes.\n- Reviewed possible microcontroller options and identified motor specifications required before final component selection.\n\nOutcome\n- Gained an understanding of the proposed motor starter architecture and its major functional blocks.\n- Prepared an initial component list to support further circuit design.\n- Identified pending technical requirements, including motor ratings, current-sensing specifications and SSR selection criteria.\n- Established the next steps for preliminary schematic development and design review.\n\nNext Plan\nPrepare the system block diagram, finalize the preliminary controller input/output requirements and begin the low-voltage control circuit schematic for the upcoming design submission.', E'admin', E'approved', E'gkbharath', NULL, NULL, NULL, NULL, NULL, E'2026-10-26T12:58:43.418Z', E'2026-10-27T03:25:13.763Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "requests" ("id", "submissionId", "type", "title", "createdBy", "createdByUsername", "createdById", "createdByRole", "createdByDesignation", "createdByEmployeeId", "createdByDepartment", "createdByPhone", "payload", "remarks", "target", "status", "forwardedTo", "uploadedFile", "signatureFrom", "signatureStatus", "officialDocument", "circular", "createdAt", "updatedAt") VALUES (E'6072', E'4461', E'attendance-report', E'Attendance report: 2026-10-26 to 2026-10-26', E'VISHNU VARSHINI M', E'vishnuu', E'SMIB-EMP-5c6151ea-f197-40ad-9eb4-69cc3e1cd5e3', E'employee', E'PCB & EMS/IoT Designer-T', E'MIB05', E'PCB Designs & Fabrication Team', E'6380551370', '{"fromDate": "2026-10-26", "toDate": "2026-10-26", "remarks": "DAILY WORK REPORT \nDate: 26 October 2026\n\n1. Servo Power Distribution Board (PDB) \u2013 Technical Analysis\n- Reviewed the servo power requirements for four servos, including continuous current of 2.8 A and peak current of 8.4 A per servo.\n- Analysed the requirement for redundant 8 V DC-DC converters, ensuring that a single converter can support the complete servo load.\n- Reviewed power distribution, load capacity, and redundancy requirements.\n\n2. Motor Starter Project \u2013 Design Review\n- Reviewed the project diagrams and technical information.\n- Analysed the project requirements to understand the system operation and major functional blocks.\n- Created block diagram and flow chart for building the schematic.\n\n3. Project Quotation Revision\n- Worked on preparing a professional quotation document with altered pricing for the Motor Starter project based on the available technical requirements.\n- Reviewed the project scope and quotation structure for clarity and professional presentation.\n\n4. Debugging in Kicad\n* Worked on the schematic of the 4 layer project and debugging of warnings related to footprints and pin configuration.", "daysRecorded": 1, "attendance": [{"id": "37537ff1-dfeb-4a35-97ec-607e1cedba91", "userId": "SMIB-EMP-5c6151ea-f197-40ad-9eb4-69cc3e1cd5e3", "username": "vishnuu", "fullName": "VISHNU VARSHINI M", "employeeId": "MIB05", "date": "2026-10-26", "checkIn": "2026-10-26T03:26:38.358Z", "checkOut": "2026-10-26T11:52:33.577Z"}], "approvalChain": ["hareeshv", "santhanakumarv", "gkbharath"], "currentApproverIndex": 2, "comments": [{"by": "gkbharath", "comment": "", "decision": "approve", "stageIndex": 2, "at": "2026-10-26T13:07:42.801Z"}, {"by": "santhanakumarv", "comment": "", "decision": "approve", "stageIndex": 1, "at": "2026-10-26T13:02:56.417Z"}, {"by": "hareeshv", "comment": "", "decision": "approve", "stageIndex": 0, "at": "2026-10-26T12:52:40.193Z"}]}'::jsonb, E'DAILY WORK REPORT \nDate: 26 October 2026\n\n1. Servo Power Distribution Board (PDB) – Technical Analysis\n- Reviewed the servo power requirements for four servos, including continuous current of 2.8 A and peak current of 8.4 A per servo.\n- Analysed the requirement for redundant 8 V DC-DC converters, ensuring that a single converter can support the complete servo load.\n- Reviewed power distribution, load capacity, and redundancy requirements.\n\n2. Motor Starter Project – Design Review\n- Reviewed the project diagrams and technical information.\n- Analysed the project requirements to understand the system operation and major functional blocks.\n- Created block diagram and flow chart for building the schematic.\n\n3. Project Quotation Revision\n- Worked on preparing a professional quotation document with altered pricing for the Motor Starter project based on the available technical requirements.\n- Reviewed the project scope and quotation structure for clarity and professional presentation.\n\n4. Debugging in Kicad\n* Worked on the schematic of the 4 layer project and debugging of warnings related to footprints and pin configuration.', E'admin', E'approved', E'gkbharath', NULL, NULL, NULL, NULL, NULL, E'2026-10-26T12:00:00.694Z', E'2026-10-26T13:07:42.802Z') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "requests" ("id", "submissionId", "type", "title", "createdBy", "createdByUsername", "createdById", "createdByRole", "createdByDesignation", "createdByEmployeeId", "createdByDepartment", "createdByPhone", "payload", "remarks", "target", "status", "forwardedTo", "uploadedFile", "signatureFrom", "signatureStatus", "officialDocument", "circular", "createdAt", "updatedAt") VALUES (E'8625', E'5730', E'report', E'Daily Work Report – Company Website Research', E'MATHIYAZHAGAN D', E'mathi', E'SMIB-EMP-ece437f0-46b4-4c26-acda-c6164dadef01', E'intern', E'PCB Design Intern', E'MIB06', E'PCB Designs & Fabrication Team', E'8056197704', '{"description": "Today, I researched the websites of DSIB Technologies, Circuitronica, RV Circuits, and Dexcel Designs. I reviewed their business domains and technical service areas, including custom PCB design, embedded hardware, IoT sensor networks, electronics design, and automation prototypes. I organized the collected information to understand each company''s technical focus.", "reportFrequency": "weekly", "reportPeriodMode": "period", "reportPeriodYear": 2026, "reportPeriodMonth": 10, "reportPeriodWeek": 44, "periodStartDate": "2026-10-26", "periodEndDate": "2026-11-01", "periodLabel": "2026-10-26", "reportDate": "2026-10-26", "attachments": [], "guideId": "SMIB-EMP-cb29066e-397b-4d3d-bd88-04ee5d654d69", "guideUsername": "sabir", "approvalChain": ["sabir", "hareeshv", "santhanakumarv", "gkbharath"], "currentApproverIndex": 2, "comments": [{"by": "santhanakumarv", "comment": "Summited Under Weekly. Summit to Attdance Page.", "decision": "reject", "stageIndex": 2, "at": "2026-10-26T13:02:42.740Z"}, {"by": "hareeshv", "comment": "", "decision": "approve", "stageIndex": 1, "at": "2026-10-26T12:52:46.987Z"}, {"by": "sabir", "comment": "", "decision": "recommend", "stageIndex": 0, "at": "2026-10-26T12:07:51.795Z"}]}'::jsonb, E'The purpose of this report is to document today''s company research activities and improve my understanding of companies working in embedded systems, PCB design, IoT, and electronics engineering. The research will help in identifying companies and their areas of specialization.', E'admin', E'rejected', E'santhanakumarv', NULL, NULL, NULL, NULL, NULL, E'2026-10-26T11:59:55.873Z', E'2026-10-26T13:02:42.741Z') ON CONFLICT ("id") DO NOTHING;
