posed activities for the upcoming TEQTIS INFO project.", "reportFrequency": "weekly", "reportPeriodMode": "period", "reportPeriodYear": 2026, "reportPeriodMonth": 10, "reportPeriodWeek": 44, "periodStartDate": "2026-10-26", "periodEndDate": "2026-11-01", "periodLabel": "2026-10-26", "reportDate": "2026-10-26", "attachments": [], "guideId": "SMIB-EMP-cb29066e-397b-4d3d-bd88-04ee5d654d69", "guideUsername": "sabir", "approvalChain": ["sabir", "hareeshv", "santhanakumarv", "gkbharath"], "currentApproverIndex": 3, "comments": [{"by": "gkbharath", "comment": "Subject to Check the Schematic Files Made By She.", "decision": "approve", "stageIndex": 3, "at": "2026-10-26T10:49:11.445Z"}, {"by": "santhanakumarv", "comment": "", "decision": "approve", "stageIndex": 2, "at": "2026-10-26T05:21:36.124Z"}, {"by": "hareeshv", "comment": "", "decision": "approve", "stageIndex": 1, "at": "2026-10-26T05:20:32.343Z"}, {"by": "sabir", "comment": "", "decision": "recommend", "stageIndex": 0, "at": "2026-10-26T05:15:52.981Z"}]}'::jsonb, E'', E'admin', E'approved', E'gkbharath', NULL, NULL, NULL, NULL, NULL, E'2026-10-26T03:40:30.066Z', E'2026-10-26T10:49:11.445Z') ON CONFLICT ("id") DO NOTHING;
